import subprocess,json,pathlib
packages=['ros-humble-navigation2','ros-humble-nav2-bringup','ros-humble-pcl-ros','ros-humble-slam-toolbox','ros-humble-rosidl-default-generators','ros-humble-ament-cmake-auto','ros-humble-nav2-core','ros-humble-tf2-ros','libpcl-dev','libeigen3-dev','libgoogle-glog-dev','libceres-dev','python3-dev','cmake','ninja-build','g++']
out={}
fmt=chr(36)+'{binary:Package} '+chr(36)+'{Version} '+chr(36)+'{db:Status-Abbrev}'+chr(10)
for p in packages:
 r=subprocess.run(['dpkg-query','-W','-f='+fmt,p],capture_output=True,text=True);out[p]={'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
old=pathlib.Path('/root/pb_ws/src/pb_rm_simulation')
out['old_workspace']={}
for args in [['remote','-v'],['rev-parse','HEAD'],['status','--porcelain=v1'],['submodule','status']]:
 r=subprocess.run(['git',*args],cwd=old,capture_output=True,text=True);out['old_workspace'][' '.join(args)]={'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
out['ros_setup_exists']=pathlib.Path('/opt/ros/humble/setup.bash').is_file()
out['old_install_exists']=pathlib.Path('/root/pb_ws/install').exists()
out['old_submodule_worktrees']={}
for rel in ['src/rm_driver/livox_ros_driver2','src/rm_localization/FAST_LIO','src/rm_localization/point_lio']:
 p=old/rel
 r=subprocess.run(['git','status','--porcelain=v1'],cwd=p,capture_output=True,text=True)
 out['old_submodule_worktrees'][rel]={'status':r.stdout,'returncode':r.returncode,'actual_file_count':sum(1 for f in p.rglob('*') if f.is_file())}
print(json.dumps(out))
